const stage=document.querySelector('#study'),canvas=document.querySelector('#world'),ctx=canvas.getContext('2d',{alpha:false});
const video=document.querySelector('#footage'),launch=document.querySelector('#launch'),replay=document.querySelector('#replay'),timeline=document.querySelector('#timeline'),next=document.querySelector('#continue'),phase=document.querySelector('#phase');
const BEGIN=1.18,END=3.247,W=1920,H=1086;
let ready=false,logo=null,playing=false,framePending=false;
const repair=document.createElement('canvas');repair.width=235;repair.height=32;const repairCtx=repair.getContext('2d',{willReadFrequently:true});
function cleanCaption(x,y,w,h){repairCtx.clearRect(0,0,235,32);repairCtx.drawImage(video,x/W*video.videoWidth,y/H*video.videoHeight,w/W*video.videoWidth,h/H*video.videoHeight,0,0,w,h);const patch=repairCtx.getImageData(0,0,w,h);for(let row=0;row<h;row++){for(let col=0;col<w;col++){for(let c=0;c<3;c++){const l=patch.data[(row*w)*4+c],r=patch.data[(row*w+w-1)*4+c];patch.data[(row*w+col)*4+c]=l+(r-l)*col/(w-1)}}}repairCtx.putImageData(patch,0,0);ctx.drawImage(repair,0,0,w,h,x,y,w,h)}
const original=new Image();original.src='../assets/lotus-original-red-gold-web.webp';
original.onload=()=>{const stamp=document.createElement('canvas');stamp.width=150;stamp.height=104;const s=stamp.getContext('2d');s.drawImage(original,0,0,150,104);const p=s.getImageData(0,0,150,104);for(let i=0;i<p.data.length;i+=4){if(p.data[i+3]<89){p.data[i+3]=0;continue}const l=(p.data[i]*.3+p.data[i+1]*.5+p.data[i+2]*.2)/255,d=((i/4%150+Math.floor(i/4/150))%2)*.055;const ink=l+d>.6?[255,255,255]:l+d>.23?[255,92,43]:l+d>.08?[240,26,11]:[115,5,4];p.data.set([...ink,255],i)}s.putImageData(p,0,0);logo=stamp;draw()};
function smooth(a,b,t){const x=Math.max(0,Math.min(1,(t-a)/(b-a)));return x*x*(3-2*x)}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);draw()}
function draw(){if(!ready||video.readyState<2)return;const t=video.currentTime,scale=Math.max(canvas.width/W,canvas.height/H),x=(canvas.width-W*scale)/2,y=(canvas.height-H*scale)/2;ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#050505';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.setTransform(scale,0,0,scale,x,y);ctx.drawImage(video,0,0,W,H);
  // Replace the reference's small caption using its adjacent clean background strip.
  if(t<1.50){cleanCaption(850,530,220,29)}
  if(t>1.72){cleanCaption(845,938,235,29)}
  const unfold=smooth(1.49,1.74,t),flash=Math.sin(unfold*Math.PI),markY=185+15*unfold,markWidth=214-45*unfold,markHeight=markWidth*104/150;
  if(logo){ctx.save();ctx.translate(960,markY);ctx.scale(1+flash*.35,Math.max(.12,Math.abs(Math.cos(unfold*Math.PI))));ctx.globalAlpha=1-flash*.7;ctx.imageSmoothingEnabled=false;ctx.drawImage(logo,-markWidth/2,-markHeight/2,markWidth,markHeight);ctx.restore()}
  ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`700 ${Math.min(28-6*unfold,(canvas.width/scale-60)/21)}px Doto,monospace`;ctx.fillStyle='#090909';ctx.globalAlpha=1-flash;ctx.fillText('EXPRESSION OVER IMPRESSION.',960,548+274*unfold);ctx.restore();
  ctx.setTransform(1,0,0,1,0,0);const progress=Math.max(0,t-BEGIN);timeline.value=String(Math.round(progress*1000));document.querySelector('#time').textContent=progress.toFixed(2).padStart(5,'0');phase.textContent=!playing&&t<=BEGIN+.02?'点击中心开启':t<1.49?'蓄势':t<1.74?'翻转 · 展开':t<3.18?'宇宙落场':'播放完成';stage.dataset.phase=t<1.49?'before':t<1.74?'unfold':'after';launch.hidden=playing||t>BEGIN+.03;next.hidden=t<3.18;launch.style.setProperty('--target-y',`${(692*scale+y)/canvas.height*100}%`);document.querySelectorAll('[data-time]').forEach(b=>b.setAttribute('aria-pressed',String(Math.abs(Number(b.dataset.time)-t)<.035)));
}
function onFrame(){framePending=false;draw();if(playing){framePending=true;if('requestVideoFrameCallback' in video)video.requestVideoFrameCallback(onFrame);else requestAnimationFrame(onFrame)}}
async function play(){if(!ready)return;video.pause();video.currentTime=BEGIN;playing=true;launch.hidden=true;next.hidden=true;replay.textContent='暂停 Ⅱ';try{await video.play();if(!framePending){framePending=true;onFrame()}}catch{playing=false;phase.textContent='点击重播';launch.hidden=false}}
function seek(t){playing=false;video.pause();video.currentTime=Math.min(END-.025,Math.max(BEGIN,t));replay.textContent='重播 ↗';draw()}
video.addEventListener('loadeddata',()=>{ready=true;video.currentTime=BEGIN;launch.disabled=replay.disabled=timeline.disabled=false;document.querySelectorAll('[data-time]').forEach(b=>b.disabled=false);draw()},{once:true});video.addEventListener('seeked',draw);video.addEventListener('ended',()=>{playing=false;replay.textContent='重播 ↗';draw();phase.textContent='播放完成';next.hidden=false});video.addEventListener('error',()=>{document.querySelector('#error').hidden=false;phase.textContent='载入失败'});
launch.addEventListener('click',play);replay.addEventListener('click',()=>{if(playing){playing=false;video.pause();replay.textContent='重播 ↗';draw()}else play()});timeline.addEventListener('input',()=>seek(BEGIN+Number(timeline.value)/1000));document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>seek(Number(b.dataset.time))));
new ResizeObserver(resize).observe(canvas);document.fonts.load('700 28px Doto').then(draw);document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){playing=false;video.pause();replay.textContent='重播 ↗'}});resize();
